function validate([circles]) {
  if (!Array.isArray(circles) || circles.length < 1 || circles.length > 200) return 'circles needs 1 to 200 entries.';
  for (const circle of circles) {
    if (!Array.isArray(circle) || circle.length !== 3 || !circle.every(Number.isInteger)) return 'Each circle is three integers [x, y, r].';
    const [x, y, r] = circle;
    if (x < 1 || x > 100 || y < 1 || y > 100) return 'Each center coordinate is between 1 and 100.';
    if (r < 1 || r > Math.min(x, y)) return 'Each radius is between 1 and min(x, y).';
  }
  return null;
}

