function countLatticePoints(circles) {
  const covered = new Set();
  for (const circle of circles) {
    const cx = circle[0], cy = circle[1], radius = circle[2];
    for (let a = cx - radius; a <= cx + radius; a++)
      for (let b = cy - radius; b <= cy + radius; b++)
        if (Math.hypot(a - cx, b - cy) <= radius + 1e-9) covered.add(a + ',' + b);
  }
  return covered.size;
}

