function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const count = size === 'large' ? 200 : pick(1, 5);
  const span = size === 'large' ? 100 : pick(1, 12);
  const circles = [];
  for (let i = 0; i < count; i++) {
    const x = pick(1, span);
    const y = pick(1, span);
    const r = pick(1, Math.min(x, y));
    circles.push([x, y, r]);
  }
  if (size === 'small' && circles.length > 1 && rand() < 0.3) circles.push([...circles[0]]);
  return [circles];
}
